-- Disposable database/RLS fixtures; rolled back without sending email or creating files.
begin;
do $$
declare admin_user uuid:=gen_random_uuid();member uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();pending_user uuid:=gen_random_uuid();
 playlist uuid:=gen_random_uuid();track uuid:=gen_random_uuid();obj text;before_count integer;value jsonb;entry jsonb;
begin
 insert into auth.users(id,email,raw_user_meta_data) values(admin_user,admin_user||'@example.invalid','{}'),(member,member||'@example.invalid','{}'),(other_user,other_user||'@example.invalid','{}'),(pending_user,pending_user||'@example.invalid','{}');
 insert into public.sb_profiles(id,display_name) values(admin_user,'Limits admin'),(member,'Limits member'),(other_user,'Other member'),(pending_user,'Pending member');
 update public.sb_account_access set status='approved' where user_id in(admin_user,member,other_user);
 insert into soundbar_private.sb_admins(user_id) values(admin_user);
 perform set_config('request.jwt.claim.sub',member::text,true);execute 'set local role authenticated';
 if (public.sb_account_state()->'limits') is distinct from '{"file":31457280,"storage":1073741824}'::jsonb then raise exception 'Default limits changed';end if;
 begin perform public.sb_admin_set_account_limits(member,1048576,10485760);raise exception 'Member changed limits';exception when insufficient_privilege then null;end;
 begin update soundbar_private.sb_account_limits set file_bytes=52428800 where user_id=member;raise exception 'Direct update allowed';exception when insufficient_privilege then null;end;
 begin perform soundbar_private.sb_effective_limits(other_user);raise exception 'Private helper exposed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',admin_user::text,true);execute 'set local role authenticated';
 perform public.sb_admin_set_account_limits(member,2097152,10485760);
 perform public.sb_admin_set_account_limits(pending_user,1048576,5242880);
 begin perform public.sb_admin_set_account_limits(member,53477376,1073741824);raise exception 'Global file ceiling bypassed';exception when raise_exception then if sqlerrm='Global file ceiling bypassed' then raise;end if;end;
 begin perform public.sb_admin_set_account_limits(member,31457280,1048576);raise exception 'Insufficient total accepted';exception when raise_exception then if sqlerrm='Insufficient total accepted' then raise;end if;end;
 value:=public.sb_admin_accounts();select x into entry from jsonb_array_elements(value)x where (x->>'user_id')::uuid=member;
 if entry->'limits' is distinct from '{"file":2097152,"storage":10485760}'::jsonb then raise exception 'Admin list missing limits';end if;
 if not entry ? 'can_delete' or not entry ? 'deletion_status' then raise exception 'Existing admin data lost';end if;
 perform set_config('request.jwt.claim.sub',member::text,true);
 if public.sb_account_state()->'limits' is distinct from '{"file":2097152,"storage":10485760}'::jsonb then raise exception 'Member limit not refreshed';end if;
 if not soundbar_private.sb_storage_quota('{"size":2097152}') or soundbar_private.sb_storage_quota('{"size":2097153}') then raise exception 'Per-file storage quota incorrect';end if;
 insert into public.sb_playlists(id,name) values(playlist,'Custom limits');
 insert into public.sb_tracks(id,playlist_id,name,audio_path,file_size) values(track,playlist,'Audio',member||'/'||track||'.mp3',2097152);
 begin update public.sb_tracks set file_size=2097153 where id=track;raise exception 'Track limit not enforced';exception when check_violation then null;end;
 obj:=member||'/'||gen_random_uuid()||'.mp3';
 insert into storage.objects(bucket_id,name,metadata) values('soundbar-audio',obj,'{"size":2097152,"mimetype":"audio/mpeg"}');
 execute 'reset role';
 -- Simulate already-saved files, then lower the quota below the current usage.
 insert into storage.objects(bucket_id,name,metadata) values('soundbar-audio',member||'/'||gen_random_uuid()||'.mp3','{"size":6291456,"mimetype":"audio/mpeg"}');
 perform set_config('request.jwt.claim.sub',member::text,true);execute 'set local role authenticated';
 if not soundbar_private.sb_storage_quota('{"size":2097152}') then raise exception 'Exact total boundary rejected';end if;
 begin insert into storage.objects(bucket_id,name,metadata) values('soundbar-audio',member||'/'||gen_random_uuid()||'.mp3','{"size":2097153,"mimetype":"audio/mpeg"}');raise exception 'RLS accepted oversized audio';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_user::text,true);perform public.sb_admin_set_account_limits(member,1048576,4194304);
 value:=public.sb_admin_accounts();select x into entry from jsonb_array_elements(value)x where (x->>'user_id')::uuid=member;
 if (entry->>'storage_bytes')::bigint<>8388608 then raise exception 'Admin usage incorrect';end if;
 perform set_config('request.jwt.claim.sub',member::text,true);
 if soundbar_private.sb_storage_quota('{"size":1}') or soundbar_private.sb_storage_quota(null) then raise exception 'Over-quota upload accepted';end if;
 if not exists(select 1 from storage.objects where name=obj) or not exists(select 1 from public.sb_tracks where id=track) then raise exception 'Reducing quota deleted existing audio';end if;
 update public.sb_tracks set name='Still editable' where id=track;
 perform set_config('request.jwt.claim.sub',other_user::text,true);
 if public.sb_account_state()->'limits' is distinct from '{"file":31457280,"storage":1073741824}'::jsonb then raise exception 'Other member affected';end if;
 perform set_config('request.jwt.claim.sub',admin_user::text,true);perform public.sb_admin_set_account_limits(member,52428800,2147483648);
 perform set_config('request.jwt.claim.sub',member::text,true);
 if not soundbar_private.sb_storage_quota('{"size":52428800}') then raise exception 'Configured 50 MB rejected';end if;
 perform set_config('request.jwt.claim.sub',admin_user::text,true);perform public.sb_admin_set_account_limits(member,31457280,1073741824);
 execute 'reset role';
 if (select count(*) from soundbar_private.sb_account_limit_audit where target=member)<>4 then raise exception 'Limit changes not audited';end if;
 if exists(select 1 from storage.buckets where id='soundbar-audio' and (file_size_limit<>52428800 or public)) then raise exception 'Private bucket ceiling incorrect';end if;
 if exists(select 1 from storage.buckets where id='soundbar-submissions' and file_size_limit<>31457280) then raise exception 'Contribution cap changed';end if;
 perform set_config('request.jwt.claim.sub','',true);execute 'set local role anon';
 begin perform public.sb_admin_set_account_limits(member,1048576,10485760);raise exception 'Anonymous access accepted';exception when insufficient_privilege then null;end;
 execute 'reset role';
end $$;
rollback;
